#!/usr/bin/env sage
"""
FIXED precision check. The recurrence is:

  u_{n+1} = (B_n/A_n) u_n - (C_{n-1}/A_{n-1}) u_{n-1} + (D_{n-2}/A_{n-2}) u_{n-2}

NOT: u_{n+1} = (B_n u_n - C_{n-1} u_{n-1} + D_{n-2} u_{n-2}) / A_n

The denominators A_n, A_{n-1}, A_{n-2} are DIFFERENT for each term!
"""


# This file was *autogenerated* from the file scratchpad/precision_check_fixed.sage
from sage.all_cmdline import *   # import sage library

_sage_const_2000 = Integer(2000); _sage_const_60 = Integer(60); _sage_const_1024 = Integer(1024); _sage_const_2 = Integer(2); _sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_9 = Integer(9); _sage_const_946 = Integer(946); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_16 = Integer(16); _sage_const_3784 = Integer(3784); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_1 = Integer(1); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_0 = Integer(0); _sage_const_215040420000 = Integer(215040420000); _sage_const_167282265043404 = Integer(167282265043404); _sage_const_905 = Integer(905); _sage_const_964185327658080 = Integer(964185327658080); _sage_const_6071 = Integer(6071); _sage_const_612218384750 = Integer(612218384750); _sage_const_9525021973931919 = Integer(9525021973931919); _sage_const_18100 = Integer(18100); _sage_const_29561828382772029 = Integer(29561828382772029); _sage_const_65380 = Integer(65380); _sage_const_50 = Integer(50); _sage_const_30 = Integer(30); _sage_const_20 = Integer(20); _sage_const_40 = Integer(40); _sage_const_15 = Integer(15); _sage_const_25 = Integer(25)
import mpmath
mpmath.mp.dps = _sage_const_2000 

N = _sage_const_60 

def A_p27(n):
    return QQ(_sage_const_1024 ) * (_sage_const_2 *n+_sage_const_5 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_946 *n**_sage_const_2 +_sage_const_6407 *n+_sage_const_10860 )

def B_p27(n):
    return QQ(_sage_const_128 ) * (_sage_const_2 *n+_sage_const_7 )**_sage_const_3  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_104060 *n**_sage_const_6  + _sage_const_1745370 *n**_sage_const_5  +
        _sage_const_12145238 *n**_sage_const_4  + _sage_const_44886481 *n**_sage_const_3  + _sage_const_92943995 *n**_sage_const_2  + _sage_const_102256019 *n + _sage_const_46709052 )

def C_p27(n):
    return QQ(_sage_const_16 ) * (n+_sage_const_3 )**_sage_const_4  * (_sage_const_2 *n+_sage_const_9 )**_sage_const_3  * (_sage_const_3784 *n**_sage_const_5  + _sage_const_57792 *n**_sage_const_4  +
        _sage_const_351019 *n**_sage_const_3  + _sage_const_1059230 *n**_sage_const_2  + _sage_const_1587211 *n + _sage_const_944620 )

def D_p27(n):
    return QQ(_sage_const_1 ) * (n+_sage_const_3 )**_sage_const_4  * (n+_sage_const_4 )**_sage_const_6  * (_sage_const_946 *n**_sage_const_2  + _sage_const_4515 *n + _sage_const_5399 )

# CORRECT recurrence: different A denominators for each term
# u_{n+1} = (B_n/A_n) u_n - (C_{n-1}/A_{n-1}) u_{n-1} + (D_{n-2}/A_{n-2}) u_{n-2}
# For n >= 2
q = [QQ(_sage_const_0 )] * N
q[_sage_const_0 ] = QQ(-_sage_const_215040420000 )
q[_sage_const_1 ] = QQ(-_sage_const_167282265043404 ) / QQ(_sage_const_905 )
q[_sage_const_2 ] = QQ(-_sage_const_964185327658080 ) / QQ(_sage_const_6071 )

for n in range(_sage_const_2 , N-_sage_const_1 ):
    q[n+_sage_const_1 ] = B_p27(n)/A_p27(n) * q[n] - C_p27(n-_sage_const_1 )/A_p27(n-_sage_const_1 ) * q[n-_sage_const_1 ] + D_p27(n-_sage_const_2 )/A_p27(n-_sage_const_2 ) * q[n-_sage_const_2 ]

p = [QQ(_sage_const_0 )] * N
p[_sage_const_0 ] = QQ(-_sage_const_612218384750 )
p[_sage_const_1 ] = QQ(-_sage_const_9525021973931919 ) / QQ(_sage_const_18100 )
p[_sage_const_2 ] = QQ(-_sage_const_29561828382772029 ) / QQ(_sage_const_65380 )

for n in range(_sage_const_2 , N-_sage_const_1 ):
    p[n+_sage_const_1 ] = B_p27(n)/A_p27(n) * p[n] - C_p27(n-_sage_const_1 )/A_p27(n-_sage_const_1 ) * p[n-_sage_const_1 ] + D_p27(n-_sage_const_2 )/A_p27(n-_sage_const_2 ) * p[n-_sage_const_2 ]

# Check first few values match
print("=== First few values ===")
for n in range(_sage_const_5 ):
    print("q_%d = %s" % (n, q[n]))
    print("p_%d = %s" % (n, p[n]))

# Compare with OLD (wrong) recurrence
q_old = [QQ(_sage_const_0 )] * _sage_const_5 
q_old[_sage_const_0 ] = QQ(-_sage_const_215040420000 )
q_old[_sage_const_1 ] = QQ(-_sage_const_167282265043404 ) / QQ(_sage_const_905 )
q_old[_sage_const_2 ] = QQ(-_sage_const_964185327658080 ) / QQ(_sage_const_6071 )

for n in range(_sage_const_2 , _sage_const_4 ):
    q_old[n+_sage_const_1 ] = (B_p27(n) * q_old[n] - C_p27(n-_sage_const_1 ) * q_old[n-_sage_const_1 ] + D_p27(n-_sage_const_2 ) * q_old[n-_sage_const_2 ]) / A_p27(n)

print("\n=== Comparing old vs new at n=3 ===")
print("q_3 (correct): %s" % q[_sage_const_3 ])
print("q_3 (old/wrong): %s" % q_old[_sage_const_3 ])
print("Difference: %s" % (q[_sage_const_3 ] - q_old[_sage_const_3 ]))

# Compute L at 2000 digits
L = mpmath.zeta(_sage_const_2 ) + mpmath.zeta(_sage_const_3 )
print("\nL = ζ(2)+ζ(3) (50 digits): %s" % mpmath.nstr(L, _sage_const_50 ))

# p/q - L
print("\n=== p_n/q_n - L (FIXED recurrence) ===")
for n in range(min(_sage_const_30 , N)):
    if q[n] != _sage_const_0 :
        p_mp = mpmath.mpf(p[n].numerator()) / mpmath.mpf(p[n].denominator())
        q_mp = mpmath.mpf(q[n].numerator()) / mpmath.mpf(q[n].denominator())
        diff = p_mp / q_mp - L
        if n <= _sage_const_20  or n % _sage_const_5  == _sage_const_0 :
            print("n=%2d: p/q - L = %s" % (n, mpmath.nstr(diff, _sage_const_40 )))

# Errors
print("\n=== e_n = p_n - L·q_n ===")
e_vals = []
for n in range(min(_sage_const_40 , N)):
    p_mp = mpmath.mpf(p[n].numerator()) / mpmath.mpf(p[n].denominator())
    q_mp = mpmath.mpf(q[n].numerator()) / mpmath.mpf(q[n].denominator())
    e = p_mp - L * q_mp
    e_vals.append(e)
    if n <= _sage_const_15 :
        print("n=%2d: e = %s" % (n, mpmath.nstr(e, _sage_const_30 )))

# Error decay rate
print("\n=== e_{n+1}/e_n ===")
for n in range(min(_sage_const_30 , len(e_vals)-_sage_const_1 )):
    if abs(e_vals[n]) > _sage_const_0 :
        ratio = e_vals[n+_sage_const_1 ] / e_vals[n]
        print("n=%2d: %s" % (n, mpmath.nstr(ratio, _sage_const_20 )))

# q ratio (Poincaré)
print("\n=== q_{n+1}/q_n ===")
for n in range(min(_sage_const_20 , N-_sage_const_1 )):
    if q[n] != _sage_const_0 :
        r = float(q[n+_sage_const_1 ]/q[n])
        print("n=%2d: %.15f" % (n, r))

# |e/q| pattern
print("\n=== |e_n/q_n| ===")
for n in range(min(_sage_const_30 , len(e_vals))):
    if q[n] != _sage_const_0 :
        q_mp = mpmath.mpf(q[n].numerator()) / mpmath.mpf(q[n].denominator())
        ratio = abs(e_vals[n] / q_mp)
        print("n=%2d: %s" % (n, mpmath.nstr(ratio, _sage_const_25 )))

